import math


def _breaks(r, h, mmax, bstep, crit):
    """Bai-Perron multiple mean shifts by dynamic programming.

    Global least squares over all partitions with segments no shorter than h,
    candidate break dates thinned to every `bstep` bars so the search stays
    affordable inside a per-bar backtest. Returns (n_segments, break_ends).
    """
    T = len(r)
    if T < 2 * h + 2:
        return 1, []
    S1 = [0.0] * (T + 1)
    S2 = [0.0] * (T + 1)
    for j in range(T):
        S1[j + 1] = S1[j] + r[j]
        S2[j + 1] = S2[j] + r[j] * r[j]

    def cost(a, b):
        L = b - a + 1
        if L <= 0:
            return 0.0
        s = S1[b + 1] - S1[a]
        q = S2[b + 1] - S2[a]
        v = q - s * s / L
        return v if v > 0 else 0.0

    ends = list(range(h - 1, T - h, bstep))
    if not ends:
        return 1, []
    prev = {}
    pback = {}
    for e in ends:
        prev[e] = cost(0, e)
        pback[e] = []
    res = {1: (cost(0, T - 1), [])}
    for k in range(2, mmax + 2):
        best = None
        for e2 in prev:
            if e2 <= T - 1 - h:
                val = prev[e2] + cost(e2 + 1, T - 1)
                if best is None or val < best[0]:
                    best = (val, pback[e2] + [e2])
        if best is None:
            break
        res[k] = best
        cur = {}
        cback = {}
        for e in ends:
            bb = None
            for e2 in prev:
                if e2 <= e - h:
                    val = prev[e2] + cost(e2 + 1, e)
                    if bb is None or val < bb[0]:
                        bb = (val, pback[e2] + [e2])
            if bb is not None:
                cur[e] = bb[0]
                cback[e] = bb[1]
        if not cur:
            break
        prev = cur
        pback = cback

    lt = math.log(T)
    bestk = 1
    bestv = None
    for k, (ssr, bl) in res.items():
        p = 2 * (k - 1) + 1
        if T - p <= 0:
            continue
        s = ssr if ssr > 1e-300 else 1e-300
        if crit == 1:
            val = math.log(s / (T - p)) + 0.299 * p * lt * lt / T
        else:
            val = math.log(s / T) + p * lt / T
        if bestv is None or val < bestv:
            bestv = val
            bestk = k
    return bestk, res[bestk][1]


def _sr(r, a, b, ann):
    L = b - a + 1
    if L < 5:
        return None
    w = r[a:b + 1]
    m = sum(w) / L
    var = sum((x - m) ** 2 for x in w) / L
    if var <= 0:
        return None
    return m / math.sqrt(var) * math.sqrt(ann)


def family_init(ctx):
    b = ctx.bars
    n = len(b)
    c = [float(x["c"]) for x in b]
    r = [0.0] * n
    for j in range(1, n):
        if c[j - 1] > 0:
            r[j] = math.log(c[j] / c[j - 1])
    ctx.r = r
    ctx.w = 0.0
    ctx.d = 0
    ctx.block = 0
    ctx.next_fit = int(ctx.p.hist) + 2
    ctx.next_chk = int(ctx.p.hist) + 2


def _fit(ctx, i):
    hist = int(ctx.p.hist)
    h = int(ctx.p.h_min)
    a0 = i - hist + 1
    if a0 < 1:
        ctx.w = 0.0
        ctx.d = 0
        return
    r = ctx.r[a0:i + 1]
    k, bl = _breaks(r, h, int(ctx.p.m_max), int(ctx.p.bstep),
                    int(ctx.p.crit))
    T = len(r)
    if bl:
        s = bl[-1] + 1
        if T - s < h and len(bl) >= 2:
            s = bl[-2] + 1
        elif T - s < h:
            s = 0
    else:
        s = 0
    sr = _sr(r, s, T - 1, float(ctx.p.ann))
    if sr is None:
        ctx.w = 0.0
        ctx.d = 0
        return
    w = abs(sr) / float(ctx.p.sr_norm)
    ctx.w = 1.0 if w > 1.0 else w
    ctx.d = 1 if sr > 0 else -1
    ctx.block = 0


def _recheck(ctx, i):
    """The daily half of the rule: a break that has just happened, into a
    losing regime, kills the allocation before the next rebalance."""
    hist = int(ctx.p.hist2)
    h = int(ctx.p.h_min)
    a0 = i - hist + 1
    if a0 < 1:
        return
    r = ctx.r[a0:i + 1]
    k, bl = _breaks(r, h, 2, int(ctx.p.bstep), int(ctx.p.crit))
    if not bl:
        return
    T = len(r)
    s = bl[-1] + 1
    if T - s > int(ctx.p.fresh):
        return
    w = r[s:T]
    if w and sum(w) / len(w) < 0:
        ctx.block = 1


def signal(ctx, i):
    if i >= ctx.next_fit:
        _fit(ctx, i)
        ctx.next_fit = i + int(ctx.p.refit)
    if i >= ctx.next_chk:
        _recheck(ctx, i)
        ctx.next_chk = i + int(ctx.p.recheck)
    if ctx.block:
        return 0
    if ctx.w < float(ctx.p.w_min):
        return 0
    return ctx.d
